/**
 * Main JavaScript file for User Profile Management Website
 * Handles frontend logic, state management, and UI component interactions
 * 
 * @file public/js/main.js
 * @version 1.0.0
 */

// Global state management using sessionStorage and DOM state
const state = {
  /**
   * Get user data from sessionStorage
   * @returns {Object|null} User object or null if not found
   */
  getUser: () => {
    try {
      const user = sessionStorage.getItem('user');
      return user ? JSON.parse(user) : null;
    } catch (error) {
      console.error('Error retrieving user from sessionStorage:', error);
      return null;
    }
  },

  /**
   * Set user data in sessionStorage
   * @param {Object} user - User object to store
   */
  setUser: (user) => {
    try {
      sessionStorage.setItem('user', JSON.stringify(user));
    } catch (error) {
      console.error('Error storing user in sessionStorage:', error);
    }
  },

  /**
   * Get authentication token from sessionStorage
   * @returns {string|null} JWT token or null if not found
   */
  getAuthToken: () => {
    return sessionStorage.getItem('authToken') || null;
  },

  /**
   * Set authentication token in sessionStorage
   * @param {string} token - JWT token to store
   */
  setAuthToken: (token) => {
    sessionStorage.setItem('authToken', token);
  },

  /**
   * Clear all authentication data from sessionStorage
   */
  clearAuth: () => {
    sessionStorage.removeItem('user');
    sessionStorage.removeItem('authToken');
  }
};

// API service for handling HTTP requests
const apiService = {
  /**
   * Make an HTTP request to the backend API
   * @param {string} endpoint - API endpoint
   * @param {Object} options - Fetch options
   * @returns {Promise<Object>} Response data
   */
  request: async (endpoint, options = {}) => {
    const defaultOptions = {
      headers: {
        'Content-Type': 'application/json',
      }
    };

    // Add auth token to headers if available
    const token = state.getAuthToken();
    if (token) {
      defaultOptions.headers['Authorization'] = `Bearer ${token}`;
    }

    const config = {
      ...defaultOptions,
      ...options
    };

    try {
      const response = await fetch(`/api${endpoint}`, config);

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.message || `HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error(`API request failed for ${endpoint}:`, error);
      throw error;
    }
  },

  /**
   * GET request
   * @param {string} endpoint - API endpoint
   * @returns {Promise<Object>} Response data
   */
  get: (endpoint) => apiService.request(endpoint, { method: 'GET' }),

  /**
   * POST request
   * @param {string} endpoint - API endpoint
   * @param {Object} data - Request body data
   * @returns {Promise<Object>} Response data
   */
  post: (endpoint, data) => apiService.request(endpoint, {
    method: 'POST',
    body: JSON.stringify(data)
  }),

  /**
   * PUT request
   * @param {string} endpoint - API endpoint
   * @param {Object} data - Request body data
   * @returns {Promise<Object>} Response data
   */
  put: (endpoint, data) => apiService.request(endpoint, {
    method: 'PUT',
    body: JSON.stringify(data)
  }),

  /**
   * DELETE request
   * @param {string} endpoint - API endpoint
   * @returns {Promise<Object>} Response data
   */
  delete: (endpoint) => apiService.request(endpoint, { method: 'DELETE' })
};

// Sidebar Navigation Component
const SidebarNavigation = {
  /**
   * Initialize sidebar navigation
   */
  init: () => {
    const sidebarToggle = document.getElementById('sidebarToggle');
    const sidebar = document.getElementById('sidebar');
    const navLinks = document.querySelectorAll('.nav-link');

    if (sidebarToggle) {
      sidebarToggle.addEventListener('click', SidebarNavigation.toggleSidebar);
    }

    navLinks.forEach(link => {
      link.addEventListener('click', SidebarNavigation.handleNavigation);
    });

    // Update active link on page load
    SidebarNavigation.updateActiveLink();
  },

  /**
   * Handle navigation link clicks
   * @param {Event} event - Click event
   */
  handleNavigation: (event) => {
    event.preventDefault();
    const target = event.currentTarget;
    const page = target.getAttribute('data-page');

    if (page) {
      // Update URL without page reload
      history.pushState({ page }, '', `#${page}`);

      // Update active link
      SidebarNavigation.updateActiveLink();

      // Load the page content
      PageManager.loadPage(page);
    }
  },

  /**
   * Toggle sidebar visibility on mobile
   */
  toggleSidebar: () => {
    const sidebar = document.getElementById('sidebar');
    sidebar.classList.toggle('active');
  },

  /**
   * Update active navigation link based on current page
   */
  updateActiveLink: () => {
    const currentPage = window.location.hash.substring(1) || 'profile';
    const navLinks = document.querySelectorAll('.nav-link');

    navLinks.forEach(link => {
      const page = link.getAttribute('data-page');
      if (page === currentPage) {
        link.classList.add('active');
      } else {
        link.classList.remove('active');
      }
    });
  }
};

// Header Bar Component
const HeaderBar = {
  /**
   * Initialize header bar
   */
  init: () => {
    const logoutBtn = document.getElementById('logoutBtn');
    if (logoutBtn) {
      logoutBtn.addEventListener('click', HeaderBar.handleLogout);
    }

    HeaderBar.updateUserDisplay();
  },

  /**
   * Handle user logout
   * @param {Event} event - Click event
   */
  handleLogout: (event) => {
    event.preventDefault();

    // Clear authentication state
    state.clearAuth();

    // Redirect to login page
    window.location.href = '/login.html';
  },

  /**
   * Update user display in header with user name
   */
  updateUserDisplay: () => {
    const user = state.getUser();
    const userNameElement = document.getElementById('userName');

    if (user && userNameElement) {
      userNameElement.textContent = user.name || user.email || 'User';
    }
  }
};

// Footer Bar Component
const FooterBar = {
  /**
   * Initialize footer bar
   */
  init: () => {
    // Currently no specific functionality needed for footer
  }
};

// Profile Form Component
const ProfileForm = {
  /**
   * Initialize profile form
   */
  init: () => {
    const form = document.getElementById('profileForm');
    if (form) {
      form.addEventListener('submit', ProfileForm.handleSubmit);
      ProfileForm.loadProfileData();
    }
  },

  /**
   * Handle form submission
   * @param {Event} event - Submit event
   */
  handleSubmit: async (event) => {
    event.preventDefault();

    const form = event.currentTarget;
    const submitBtn = form.querySelector('button[type="submit"]');
    const originalBtnText = submitBtn.textContent;

    // Show loading state
    submitBtn.disabled = true;
    submitBtn.textContent = 'Saving...';

    try {
      // Validate form
      const isValid = ProfileForm.validateForm();
      if (!isValid) {
        return;
      }

      // Get form data
      const formData = new FormData(form);
      const userData = {
        name: formData.get('name'),
        email: formData.get('email'),
        phone: formData.get('phone'),
        bio: formData.get('bio')
      };

      // Update user profile
      const response = await apiService.put('/users/profile', userData);

      // Update state with new user data
